-- Persist only a bounded plain-text name; usernames remain generated by the server.
create or replace function public.create_user_profile() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
 insert into public.profiles(user_id,username,name)
 values(new.id,'user_' || left(replace(new.id::text,'-',''),24),
   coalesce(left(btrim(new.raw_user_meta_data->>'name'),80),''));
 return new;
end $$;
revoke all on function public.create_user_profile() from public, anon, authenticated;
